#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <vector>
#include <algorithm>
#include <iomanip>
using namespace std;

struct Trasa {
    string miastoA, miastoB;
    int dystans;
};

int main() {
    ifstream f1("miasta.txt"), f2("trasy.txt");
    map<int, string> miasta;
    int id;
    string nazwa;
    while (f1 >> id >> nazwa) {
        miasta[id] = nazwa;
    }

    vector<Trasa> trasy;
    map<string, int> polaczenia;
    int a, b, d;
    int sumaD = 0;
    while (f2 >> a >> b >> d) {
        trasy.push_back({miasta[a], miasta[b], d});
        polaczenia[miasta[a]]++;
        polaczenia[miasta[b]]++;
        sumaD += d;
    }

    sort(trasy.begin(), trasy.end(), [](const Trasa &x, const Trasa &y) {
        return x.dystans < y.dystans;
    });

    cout << "a) Trasy (rosnaco wg dystansu):" << endl;
    for (auto &t : trasy) {
        cout << "   " << t.miastoA << " - " << t.miastoB << ": " << t.dystans << " km" << endl;
    }

    vector<pair<int, string>> rankPol;
    for (auto &p : polaczenia) {
        rankPol.push_back({p.second, p.first});
    }
    sort(rankPol.begin(), rankPol.end(), [](auto &x, auto &y) {
        if (x.first != y.first) return x.first > y.first;
        return x.second < y.second;
    });

    cout << endl << "b) Liczba polaczen (malejaco):" << endl;
    for (auto &r : rankPol) {
        cout << "   " << r.second << ": " << r.first << endl;
    }

    cout << endl << "c) Najkrotsza: " << trasy[0].miastoA << " - " << trasy[0].miastoB
         << " (" << trasy[0].dystans << " km)" << endl;
    cout << "   Najdluzsza: " << trasy.back().miastoA << " - " << trasy.back().miastoB
         << " (" << trasy.back().dystans << " km)" << endl;

    cout << endl << "d) Sredni dystans: " << fixed << setprecision(2)
         << (double)sumaD / trasy.size() << " km" << endl;
    return 0;
}
```

